using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using System.Globalization;
namespace Scheldemist.Native.Services;
public sealed partial class NativeHaggle
{
    private static readonly string[] Claims={"stale_goods","regular_customer","cheaper_elsewhere","buy_several","hard_up","flattery","quality","none"};
    private static readonly string[] Manners={"polite","plain","rude","threatening","nonsense"};
    private static uint Hash(string text){uint h=2166136261;foreach(char c in text)h=unchecked((h^c)*16777619);return h;}
    public static JsonObject GoodsFact(string npc,string kind,int day,double hour)
    {
        double roll=Hash(npc+":"+kind+":"+day)%10000/10000.0;bool stale;string words;switch(kind){case "herring":(stale,words)=day%7==1?(true,"Saturday's herring: no boats came in on the Sunday"):roll<.25?(true,"yesterday's herring, left over"):hour>=16?(true,"out on the table since dawn"):(false,"in off the boats this morning");break;case "eel":(stale,words)=roll<.3?(true,"smoked last week, dry by now"):(false,"smoked this week");break;case "bread":(stale,words)=roll<.2?(true,"yesterday's loaves"):hour>=15?(true,"baked at five this morning, going hard"):(false,"out of the oven this morning");break;case "apple":(stale,words)=roll<.2?(true,"bruised, from the bottom of the basket"):(false,"sound and crisp");break;case "newspaper":(stale,words)=hour>=14?(true,"this morning's paper, old news by now"):(false,"this morning's paper");break;case "soup":(stale,words)=(false,"made today");break;default:(stale,words)=(false,"goods that keep; they do not go old");break;}return new(){["stale"]=stale,["words"]=words};
    }
    public static JsonObject RatingByWords(string text)
    {
        text=text.ToLowerInvariant();bool Match(string pattern)=>Regex.IsMatch(text,pattern);var claims=new List<string>();if(Match(@"\b(old|stale|yesterday'?s?|two days|three days|rotten|smells|going off|dry|hard as)\b"))claims.Add("stale_goods");if(Match(@"\b(every day|each day|every morning|always buy|regular|often|loyal|always come)\b"))claims.Add("regular_customer");if(Match(@"\b(cheaper|down the (quay|street|road|lane)|elsewhere|other stall|next stall|over there sells)\b"))claims.Add("cheaper_elsewhere");if(Match(@"\b(two|three|four|several|a few|half a dozen|a dozen)\b")&&Match(@"\b(buy|take|have)\b"))claims.Add("buy_several");if(Match(@"\b(hungry|starving|poor|no money|children|sick|mother|nothing to eat|broke|a widow)\b"))claims.Add("hard_up");if(Match(@"\b(beautiful|lovely|finest|best (fish|bread|stall|herring|apples)|handsome|pretty|kind face)\b"))claims.Add("flattery");string manner=Match(@"\b(or else|i'?ll (smash|break|burn|hurt)|you'?ll regret|watch yourself|burn your)\b")?"threatening":Match(@"\b(thief|robber|cheat|swindler|fool|idiot|cow|pig|swine|bastard|damn|crook)\b")?"rude":Match(@"\b(please|kindly|madam|sir|missus|if you would|thank)\b")?"polite":"plain";return new(){["claims"]=Strings(claims.Take(3)),["reasonable"]=Math.Min(2,claims.Count),["manner"]=manner};
    }
    public JsonObject Supported(JsonObject rating,string text){var claims=A(rating["claims"]).Select(v=>v!.GetValue<string>()).Where(c=>Claims.Contains(c)&&(c=="none"||Facts["support"]?[c]==null||Regex.IsMatch(text,S(Facts["support"],c),RegexOptions.IgnoreCase))).ToArray();return new(){["claims"]=Strings(claims),["reasonable"]=Math.Min((int)N(rating,"reasonable"),claims.Any(c=>c!="none")?3:1),["manner"]=S(rating,"manner")};}
    private static bool? ClaimTrue(string claim,JsonObject f)=>claim switch{"stale_goods"=>B(f,"stale"),"regular_customer"=>B(f,"regular"),"cheaper_elsewhere"=>B(f,"cheaper"),"buy_several"=>B(f,"several"),"hard_up"=>B(f,"hardUp"),_=>null};
    public static JsonObject Decide(JsonObject rating,JsonObject f,JsonObject seller,Func<double> rng)
    {
        var stats=seller["stats"]!;var claims=A(rating["claims"]).Select(v=>v!.GetValue<string>()).Where(c=>c!="none").Distinct().ToArray();var truths=new List<string>();var caught=new List<string>();var why=new List<string>();string manner=S(rating,"manner");double[] rates={0,.3,.6,1};int reasonable=(int)N(rating,"reasonable");double score=manner=="nonsense"?0:reasonable>=0&&reasonable<4?rates[reasonable]:0;
        if(manner!="nonsense"){foreach(string claim in claims){var truth=ClaimTrue(claim,f);if(truth==true){truths.Add(claim);double weight=claim=="stale_goods"?1.4:claim is "regular_customer"or"cheaper_elsewhere"?1:claim=="buy_several"?.7:.6*(.5+N(stats,"warmth")/10);score+=weight;why.Add(claim+" true: +"+weight.ToString("F2",CultureInfo.InvariantCulture));}else if(truth==false){double chance=claim switch{"stale_goods"=>.85,"regular_customer"=>.9,"cheaper_elsewhere"=>.7,"buy_several"=>.4,"hard_up"=>.35,_=>.5};if(rng()<chance){caught.Add(claim);why.Add(claim+" a lie, found out");}else{score+=.3;why.Add(claim+" a lie, not found out: +0.3");}}else if(claim=="quality")score+=.3;else if(claim=="flattery"){double weight=N(stats,"warmth")>=6?.4:N(stats,"greed")>=7?-.2:.1;score+=weight;why.Add("flattery: "+weight.ToString(CultureInfo.InvariantCulture));}}
            score+=manner=="polite"?.3:manner=="rude"?-1:manner=="threatening"?-2:0;score+=-(N(stats,"greed")-5)*.2+(N(stats,"warmth")-5)*.1+N(f,"trust")*.12;if(N(f,"market")>1.05)score-=.4;else if(N(f,"market")<.95)score+=.4;if(B(f,"perishable")&&f["hoursLeft"]!=null)score+=N(f,"hoursLeft")<=1.5?1.2:N(f,"hoursLeft")<=3?.5:0;score-=.6*N(f,"triesToday");score-=.8*Math.Min(2,N(f,"liesBefore"));}
        bool refuse=false;int refuseMin=0;if(manner is "rude"or"threatening"){double t=Math.Max(0,N(stats,"temper")-5),chance=manner=="threatening"?.6+t*.06:.2+t*.08+(caught.Count>0?.15:0);if(rng()<chance){refuse=true;refuseMin=manner=="threatening"?1440:60+(int)N(stats,"temper")*10;why.Add(manner+": refused");}}double cut=caught.Count>0||refuse?0:Math.Clamp(score*.1,0,.4),price=Math.Min(N(f,"list_c"),Math.Max(N(f,"floor_c"),Math.Floor(N(f,"list_c")*(1-cut)+.5)));string outcome=refuse?"refuse":caught.Count>0?"caught":price<N(f,"list_c")?"yield":"hold";return new(){["outcome"]=outcome,["price_c"]=outcome=="yield"?price:N(f,"list_c"),["cut"]=cut,["score"]=score,["caught"]=Strings(caught),["truths"]=Strings(truths),["refuseMin"]=refuseMin,["why"]=Strings(why)};
    }
    private static string Digits(string line){var units=new Dictionary<string,int>();string[] words={"one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve"};for(int i=0;i<words.Length;i++)units[words[i]]=i+1;foreach(var p in new[]{("fifteen",15),("twenty",20),("thirty",30),("forty",40),("fifty",50),("sixty",60),("seventy",70),("eighty",80),("ninety",90),("hundred",100)})units[p.Item1]=p.Item2;return Regex.Replace(line,@"\b(twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|hundred)(?:[- ](one|two|three|four|five|six|seven|eight|nine))?\b",m=>(units[m.Groups[1].Value.ToLowerInvariant()]+(m.Groups[2].Success?units[m.Groups[2].Value.ToLowerInvariant()]:0)).ToString(),RegexOptions.IgnoreCase);}
    public static bool LineOk(string line)=>!Regex.IsMatch(Digits(line),@"\d+\s*(?:centimes?|c\b|francs?|sous|cents?)|\b(for free|for nothing|free of charge|no charge|gratis|take it free|on the house)\b|\b(knife|knives|pistol|revolver|gun|sabre|sword|cudgel|kill|murder|blood|stab|shoot)\b",RegexOptions.IgnoreCase);
}

